#[ignore]
fn deletes_the_element_with_the_specified_value_from_the_list() {
    let mut list = DoublyLinkedList::<u32>::new();
    list.push(71);
    list.push(83);
    list.push(79);
    list.delete(83);
    assert_eq!(list.len(), 2);
    assert_eq!(list.pop(), Option::Some(79));
    assert_eq!(list.shift(), Option::Some(71));
