#[test]
#[ignore]
fn delete_does_not_modify_the_list_if_the_element_is_not_found() {
    let mut list = DoublyLinkedList::<u32>::new();
    list.push(89);
    list.delete(103);
    assert_eq!(list.len(), 1);
